const listAcceptedMemory = `-- name: ListAcceptedMemory :many
SELECT id, project_id, kind, title, body, status, source, created_at, updated_at, roles, paths FROM memory WHERE project_id = ? AND status = 'accepted' ORDER BY id DESC
`

func (q *Queries) ListAcceptedMemory(ctx context.Context, projectID string) ([]Memory, error) {
	rows, err := q.db.QueryContext(ctx, listAcceptedMemory, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Memory{}
	for rows.Next() {
		var i Memory
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Kind,
			&i.Title,
			&i.Body,
			&i.Status,
			&i.Source,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Roles,
			&i.Paths,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

